  final String? accountId;
  final String handle;
  final String method;
  final String state;
  final DartHandleRegistrationJoinRequiredPreparation? joinRequired;
  final DartDefaultIdentityChange? defaultIdentityChange;
  final List<String> warnings;

  const DartHandleRegistrationResult({
    this.identity,
    this.accountId,
    required this.handle,
    required this.method,
    required this.state,
    this.joinRequired,
    this.defaultIdentityChange,
    required this.warnings,
  });

  @override
  int get hashCode =>
      identity.hashCode ^
      accountId.hashCode ^
      handle.hashCode ^
      method.hashCode ^
      state.hashCode ^
      joinRequired.hashCode ^
      defaultIdentityChange.hashCode ^
      warnings.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is DartHandleRegistrationResult &&
          runtimeType == other.runtimeType &&
          identity == other.identity &&
          accountId == other.accountId &&
          handle == other.handle &&
          method == other.method &&
          state == other.state &&
          joinRequired == other.joinRequired &&
          defaultIdentityChange == other.defaultIdentityChange &&
          warnings == other.warnings;
}

enum DartIdentityDeviceMode { legacy, vNext }

enum DartIdentityDeviceReadiness {
  legacy,
  memberReady,
  adminAwaitingRoot,
  adminReady,
  blocked,
}

enum DartIdentityDeviceRole { member, admin }

