  const DartIdentitySelector._();

  const factory DartIdentitySelector.default_() = DartIdentitySelector_Default;
  const factory DartIdentitySelector.id({required String id}) =
      DartIdentitySelector_Id;
  const factory DartIdentitySelector.did({required String did}) =
      DartIdentitySelector_Did;
  const factory DartIdentitySelector.handle({required String handle}) =
      DartIdentitySelector_Handle;
  const factory DartIdentitySelector.localAlias({required String alias}) =
      DartIdentitySelector_LocalAlias;
}

